<?php require 'config.php'; need(['nurse','doctor']); check();
$id=(int)($_GET['id']??0);$err='';
$q=function($sql,$a=[])use($pdo){$s=$pdo->prepare($sql);$s->execute($a);return $s->fetchAll();};
$ck=function($k){return isset($_POST[$k])?1:0;};$nv=function($k){return ($_POST[$k]??'')===''?null:$_POST[$k];};
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(isset($_POST['admit'])){$mom=$q('SELECT * FROM patients WHERE id=?',[(int)$_POST['mother']]);$mom=$mom[0]??null;$bw=(int)$_POST['bw'];$gw=(int)$_POST['gw'];$birth=str_replace('T',' ',$_POST['birth']);
    if(!$mom||$bw<300||$bw>6500||$gw<20||$gw>45||!$birth)$err='Choose the mother and enter a valid birth weight (300 to 6500 g), gestation (20 to 45 weeks) and birth time.';
    else{$pdo->beginTransaction();$sx=in_array($_POST['sex'],['Male','Female'])?$_POST['sex']:'Other';$nm=trim($_POST['bname'])?:'Baby of '.$mom['first_name'];
      $pdo->prepare('INSERT INTO patients(first_name,last_name,gender,dob,phone,address,next_of_kin,nok_phone) VALUES(?,?,?,?,?,?,?,?)')->execute([$nm,$mom['last_name'],$sx,substr($birth,0,10),$mom['phone'],$mom['address'],$mom['first_name'].' '.$mom['last_name'].' (mother)',$mom['phone']]);
      $bid=$pdo->lastInsertId();$pdo->prepare('UPDATE patients SET patient_no=? WHERE id=?')->execute(['P'.date('y').sprintf('%05d',$bid),$bid]);
      $dep=(int)$pdo->query("SELECT id FROM departments WHERE slug='nbu'")->fetchColumn();
      $pdo->prepare("INSERT INTO visits(patient_id,dept_id,reason,status) VALUES(?,?,?,'admitted')")->execute([$bid,$dep,'NBU admission: '.$_POST['reason']]);$vid=$pdo->lastInsertId();
      $pdo->prepare('INSERT INTO nbu_admissions(baby_patient_id,mother_patient_id,visit_id,birth_at,sex,gestation_weeks,birth_weight_g,apgar1,apgar5,apgar10,delivery_mode,place_of_birth,reason,cot_no,resp_support,feeding,phototherapy,kmc,vit_k,bcg,opv0,hepb,eye_prophylaxis,maternal_notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
        ->execute([$bid,$mom['id'],$vid,$birth,$sx,$gw,$bw,$nv('a1'),$nv('a5'),$nv('a10'),$_POST['mode'],$_POST['place'],$_POST['reason'],trim($_POST['cot']),$_POST['resp'],$_POST['feeding'],$ck('photo'),$ck('kmc'),$ck('vitk'),$ck('bcg'),$ck('opv0'),$ck('hepb'),$ck('eye'),trim($_POST['mnotes']),user()['id']]);
      $aid=$pdo->lastInsertId();$pdo->commit();audit("NBU admission $aid");header('Location: nbu.php?id='.$aid);exit;}}
  elseif(isset($_POST['chart'])){$aid=(int)$_POST['chart'];$pdo->prepare('INSERT INTO nbu_charts(adm_id,temp,hr,rr,spo2,weight_g,feed_type,feed_ml,notes,nurse_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$aid,$nv('temp'),$nv('hr'),$nv('rr'),$nv('spo2'),$nv('wt'),$_POST['ft'],$nv('fml'),trim($_POST['notes']),user()['id']]);audit("NBU chart $aid");header("Location: nbu.php?id=$aid");exit;}
  elseif(isset($_POST['outcome'])){$aid=(int)$_POST['outcome'];$st=$_POST['status'];$a=$q('SELECT visit_id FROM nbu_admissions WHERE id=?',[$aid]);
    if(in_array($st,['discharged','referred','died'])&&$a){$pdo->prepare('UPDATE nbu_admissions SET status=?,outcome_at=NOW(),discharge_weight_g=?,discharge_notes=?,phototherapy=0 WHERE id=?')->execute([$st,$nv('dw'),trim($_POST['dn']),$aid]);
      if($a[0]['visit_id'])$pdo->prepare('UPDATE visits SET status=? WHERE id=?')->execute([$st=='died'?'done':'billing',$a[0]['visit_id']]);audit("NBU outcome $st $aid");}
    header("Location: nbu.php?id=$aid");exit;}
}
$flag=function($v,$lo,$hi){return ($v!==null&&($v<$lo||$v>$hi))?' class=err':'';};
$age=function($t){$h=floor((time()-strtotime($t))/3600);return $h<48?$h.' hours':floor($h/24).' days';};
$A=null;if($id){$A=$q('SELECT a.*,b.first_name,b.last_name,b.patient_no,b.id_number,b.phone,b.gender,b.dob,m.first_name mf,m.last_name ml,m.patient_no mno FROM nbu_admissions a JOIN patients b ON b.id=a.baby_patient_id LEFT JOIN patients m ON m.id=a.mother_patient_id WHERE a.id=?',[$id]);$A=$A[0]??null;if(!$A)die('Record not found.');}
if($A&&isset($_GET['print'])){$p=$q('SELECT * FROM patients WHERE id=?',[$A['baby_patient_id']])[0];echo doc_open('NBU summary',$p,['id'=>$A['visit_id']]);
  echo '<table><tr><td>Mother<td>'.e($A['mf'].' '.$A['ml'].' ('.$A['mno'].')').'<tr><td>Born<td>'.e($A['birth_at']).' at '.e($A['gestation_weeks']).' weeks, '.e($A['birth_weight_g']).' g<tr><td>APGAR 1/5/10<td>'.e($A['apgar1'].'/'.$A['apgar5'].'/'.$A['apgar10']).'<tr><td>Delivery<td>'.e($A['delivery_mode'].', '.$A['place_of_birth']).'<tr><td>Admitted for<td>'.e($A['reason']).' on '.e($A['admitted_at']).'<tr><td>Birth care<td>Vit K '.($A['vit_k']?'yes':'no').', BCG '.($A['bcg']?'yes':'no').', OPV0 '.($A['opv0']?'yes':'no').', Hep B '.($A['hepb']?'yes':'no').', eye care '.($A['eye_prophylaxis']?'yes':'no').'<tr><td>Outcome<td>'.e($A['status']).' '.e($A['outcome_at']).'<tr><td>Discharge weight<td>'.e($A['discharge_weight_g']).' g</table><p>'.nl2br(e($A['discharge_notes'])).'</p>';
  echo doc_close('nbu.php?id='.$id);exit;}
head($A?'NBU: '.$A['first_name'].' '.$A['last_name'].' ('.$A['patient_no'].')':'NBU: New Born Unit');if($err)echo '<p class=err>'.e($err).'</p>';
if($A):$ch=$q('SELECT * FROM nbu_charts WHERE adm_id=? ORDER BY id DESC',[$id]);$lw=null;foreach($ch as $c)if($c['weight_g']){$lw=$c['weight_g'];break;}?>
<div class=card><p><a href="nbu.php">All babies</a> | <a href="nbu.php?id=<?=$id?>&print=1" target=_blank>Print summary</a> | <a href="notes.php?visit=<?=(int)$A['visit_id']?>">Doctor/nurse notes</a></p>
<table><tr><td>Mother<td><?=e($A['mf'].' '.$A['ml'].' ('.$A['mno'].')')?><td>Age<td><?=$age($A['birth_at'])?>
<tr><td>Born<td><?=e($A['birth_at'])?><td>Sex<td><?=e($A['sex'])?><tr><td>Gestation<td><?=$A['gestation_weeks']?> weeks<td>Birth weight<td><?=$A['birth_weight_g']?> g<?php if($lw)echo ' | now '.$lw.' g ('.round(($lw-$A['birth_weight_g'])/$A['birth_weight_g']*100,1).'%)';?>
<tr><td>APGAR 1/5/10<td><?=e($A['apgar1'].'/'.$A['apgar5'].'/'.$A['apgar10'])?><td>Delivery<td><?=e($A['delivery_mode'].', '.$A['place_of_birth'])?>
<tr><td>Admitted for<td><?=e($A['reason'])?><td>Cot / incubator<td><?=e($A['cot_no'])?><tr><td>Respiratory support<td><?=e($A['resp_support'])?><td>Feeding<td><?=e($A['feeding'])?>
<tr><td>Care<td colspan=3>Phototherapy: <?=$A['phototherapy']?'on':'no'?> | Kangaroo care: <?=$A['kmc']?'yes':'no'?> | Vit K <?=$A['vit_k']?'given':'not given'?> | BCG <?=$A['bcg']?'given':'no'?> | OPV0 <?=$A['opv0']?'given':'no'?> | Hep B <?=$A['hepb']?'given':'no'?> | Eye prophylaxis <?=$A['eye_prophylaxis']?'given':'no'?>
<tr><td>Maternal history<td colspan=3><?=e($A['maternal_notes'])?><tr><td>Status<td colspan=3><b><?=e($A['status'])?></b> <?=e($A['outcome_at'])?></table></div>
<?php if($A['status']=='admitted'):?><div class=card><h3>Add chart entry</h3><form method=post class=g><?=field()?><input type=hidden name=chart value=<?=$id?>>
<div><label>Temp (C)</label><input name=temp type=number step=0.1></div><div><label>Heart rate</label><input name=hr type=number></div><div><label>Resp. rate</label><input name=rr type=number></div><div><label>SpO2 (%)</label><input name=spo2 type=number max=100></div>
<div><label>Weight (g)</label><input name=wt type=number></div><div><label>Feed</label><select name=ft><option>Breast<option>Cup<option>NG tube<option>IV fluids<option>None</select></div><div><label>Feed volume (ml)</label><input name=fml type=number></div><div><label>Notes</label><input name=notes></div><div><button>Save entry</button></div></form></div><?php endif;?>
<div class=card><h3>Chart history</h3><p><small>Red values are outside the usual newborn range (temp 36.5 to 37.5, heart rate 100 to 180, breathing 30 to 60, SpO2 90 or more). They are only a guide: follow the unit protocol.</small></p>
<table><tr><th>Time<th>Temp<th>HR<th>RR<th>SpO2<th>Weight<th>Feed<th>Notes</tr>
<?php foreach($ch as $c)echo '<tr><td>'.substr($c['recorded_at'],0,16).'<td'.$flag($c['temp'],36.5,37.5).'>'.e($c['temp']).'<td'.$flag($c['hr'],100,180).'>'.e($c['hr']).'<td'.$flag($c['rr'],30,60).'>'.e($c['rr']).'<td'.$flag($c['spo2'],90,100).'>'.e($c['spo2']).'<td>'.e($c['weight_g']).'<td>'.e($c['feed_type'].' '.$c['feed_ml']).'<td>'.e($c['notes']);?></table></div>
<?php if($A['status']=='admitted'):?><div class=card><h3>Outcome</h3><form method=post class=g><?=field()?><input type=hidden name=outcome value=<?=$id?>><div><label>Outcome</label><select name=status><option value=discharged>Discharged home<option value=referred>Referred<option value=died>Died</select></div>
<div><label>Weight at outcome (g)</label><input name=dw type=number></div><div style="grid-column:1/-1"><label>Notes, advice, follow-up date</label><textarea name=dn></textarea><button>Save outcome</button></div></form></div><?php endif;
else:
$mothers=$q("SELECT id,patient_no,first_name,last_name FROM patients WHERE gender='Female' ORDER BY id DESC LIMIT 300");?>
<div class=card><h3>Babies in the unit</h3><table><tr><th>Baby<th>Age<th>Weeks<th>Birth wt<th>Latest wt<th>Cot<th>Support<th>Reason<th>Status<th></tr>
<?php foreach($q("SELECT a.*,b.first_name,b.last_name,b.patient_no,(SELECT weight_g FROM nbu_charts WHERE adm_id=a.id AND weight_g IS NOT NULL ORDER BY id DESC LIMIT 1) lw FROM nbu_admissions a JOIN patients b ON b.id=a.baby_patient_id ORDER BY a.status='admitted' DESC,a.id DESC LIMIT 60") as $a)
echo '<tr><td>'.e($a['patient_no'].' '.$a['first_name'].' '.$a['last_name']).'<td>'.$age($a['birth_at']).'<td>'.$a['gestation_weeks'].'<td>'.$a['birth_weight_g'].'<td>'.e($a['lw']).'<td>'.e($a['cot_no']).'<td>'.e($a['resp_support']).'<td>'.e($a['reason']).'<td>'.e($a['status']).'<td><a href="nbu.php?id='.$a['id'].'">Open</a>';?></table></div>
<div class=card><h3>Admit a newborn</h3><p>The mother must already be registered in Records. A patient record is created for the baby.</p><form method=post class=g><?=field()?><input type=hidden name=admit value=1>
<div><label>Mother</label><select name=mother><?php foreach($mothers as $m)echo '<option value='.$m['id'].'>'.e($m['patient_no'].' '.$m['first_name'].' '.$m['last_name']);?></select></div>
<div><label>Baby name (optional)</label><input name=bname placeholder="Baby of ..."></div><div><label>Sex</label><select name=sex><option>Female<option>Male<option>Other</select></div><div><label>Date and time of birth</label><input type=datetime-local name=birth max="<?=date('Y-m-d\TH:i')?>" required></div>
<div><label>Gestation (weeks)</label><input name=gw type=number min=20 max=45 required></div><div><label>Birth weight (g)</label><input name=bw type=number min=300 max=6500 required></div>
<div><label>APGAR 1 min</label><input name=a1 type=number min=0 max=10></div><div><label>APGAR 5 min</label><input name=a5 type=number min=0 max=10></div><div><label>APGAR 10 min</label><input name=a10 type=number min=0 max=10></div>
<div><label>Mode of delivery</label><select name=mode><option>SVD<option>Caesarean section<option>Assisted (vacuum/forceps)<option>Breech</select></div><div><label>Place of birth</label><select name=place><option>This hospital<option>Born before arrival<option>Home<option>Other facility</select></div>
<div><label>Reason for admission</label><select name=reason><option>Prematurity<option>Low birth weight<option>Birth asphyxia<option>Neonatal sepsis<option>Neonatal jaundice<option>Respiratory distress<option>Hypoglycaemia<option>Congenital abnormality<option>Other</select></div>
<div><label>Cot / incubator no.</label><input name=cot></div><div><label>Respiratory support</label><select name=resp><option>None<option>Oxygen<option>CPAP<option>Ventilator</select></div><div><label>Feeding</label><select name=feeding><option>Breastfeeding<option>Expressed milk by cup<option>NG tube<option>IV fluids (nil by mouth)</select></div>
<div style="grid-column:1/-1"><label style="font-weight:400"><input type=checkbox name=photo style="width:auto"> Phototherapy</label><label style="font-weight:400"><input type=checkbox name=kmc style="width:auto"> Kangaroo mother care</label><label style="font-weight:400"><input type=checkbox name=vitk style="width:auto"> Vitamin K given</label><label style="font-weight:400"><input type=checkbox name=bcg style="width:auto"> BCG given</label><label style="font-weight:400"><input type=checkbox name=opv0 style="width:auto"> OPV 0 given</label><label style="font-weight:400"><input type=checkbox name=hepb style="width:auto"> Hepatitis B birth dose given</label><label style="font-weight:400"><input type=checkbox name=eye style="width:auto"> Eye prophylaxis given</label>
<label>Maternal history and risk factors (antenatal care, infections, labour problems)</label><textarea name=mnotes></textarea><button>Admit to NBU</button></div></form></div><?php endif;foot();
